model User {
  id      String   @id @default(uuid())
  email   String   @unique
  profile Profile? // Optional 1:1 relation
}

model Profile {
  id     String @id @default(uuid())
  bio    String?
  userId String @unique @map("user_id") // @unique turns 1-N into 1-1
  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)
}

import { prisma } from '@/lib/prisma';

// Query User with their profile
const userWithProfile = await prisma.user.findUnique({
  where: { email: 'sarah@example.com' },
  include: { profile: true }
});

// Upsert Profile directly from the User model
const updated = await prisma.user.update({
  where: { id: userWithProfile?.id },
  data: {
    profile: {
      upsert: {
        create: { bio: 'Senior Engineer' },
        update: { bio: 'Principal Architect' }
      }
    }
  }
});
